const headers = ($json && $json.headers) ? $json.headers : {};
const body = ($json && $json.body) ? $json.body : ($json ?? {});
const env = $env || {};

function getHeader(name) {
  const lower = String(name || '').toLowerCase();
  if (headers[lower] !== undefined) return headers[lower];
  if (headers[name] !== undefined) return headers[name];
  const key = Object.keys(headers).find((k) => k.toLowerCase() === lower);
  return key ? headers[key] : undefined;
}

function isTruthy(value) {
  if (value === undefined || value === null) return false;
  const v = String(value).trim().toLowerCase();
  return ['1', 'true', 'yes', 'y', 'on', 'enabled'].includes(v);
}

function pickFirst(paths, fallback = null) {
  for (const path of paths) {
    const parts = String(path).split('.').filter(Boolean);
    let cur = body;
    for (const part of parts) {
      if (cur === null || cur === undefined) {
        cur = undefined;
        break;
      }
      cur = cur?.[part];
    }
    if (cur !== undefined && cur !== null && String(cur).trim() !== '') return cur;
  }
  return fallback;
}

function parseJsonMap(text) {
  const raw = String(text || '').trim();
  if (!raw) return null;
  try {
    const parsed = JSON.parse(raw);
    if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) return parsed;
  } catch (error) {}
  return null;
}

function parseYamlMap(text) {
  const map = {};
  const lines = String(text || '').split(/\r?\n/);
  for (const line of lines) {
    const trimmed = String(line || '').trim();
    if (!trimmed || trimmed.startsWith('#')) continue;
    const idx = trimmed.indexOf(':');
    if (idx <= 0) continue;
    const key = trimmed.slice(0, idx).trim();
    let value = trimmed.slice(idx + 1).trim();
    if (!key) continue;
    if ((value.startsWith('"') && value.endsWith('"')) || (value.startsWith("'") && value.endsWith("'"))) {
      value = value.slice(1, -1);
    }
    map[key] = value;
  }
  return map;
}

function loadRealmMap(jsonText, yamlText) {
  const jsonMap = parseJsonMap(jsonText);
  if (jsonMap && Object.keys(jsonMap).length) return jsonMap;
  return parseYamlMap(yamlText);
}

function looksLikeYamlMap(text) {
  const t = String(text || '').trim();
  if (!t) return false;
  if (/^https?:\/\//i.test(t)) return false;
  if (t.includes(String.fromCharCode(10)) || t.includes(String.fromCharCode(13)) || t.includes('\\n')) return true;
  if (/^\s*(default|\*)\s*:\s*\S+/i.test(t)) return true;
  return false;
}

function resolveGitlabWebhookSecretsMap() {
  const json = String(env.GITLAB_WEBHOOK_SECRETS_JSON || '').trim();
  const yaml = String(env.GITLAB_WEBHOOK_SECRETS_YAML || '').trim();
  if (json || yaml) return loadRealmMap(json, yaml);
  const raw = String(env.GITLAB_WEBHOOK_SECRET || '').trim();
  if (looksLikeYamlMap(raw)) return loadRealmMap('', raw);
  return {};
}

function deriveRealmFromProjectPath(path) {
  const p = String(path || '').trim();
  if (!p) return '';
  const first = p.split('/')[0] || '';
  return first.trim();
}

function normalizeLabels(labelsRaw) {
  const labels = Array.isArray(labelsRaw) ? labelsRaw : [];
  const out = [];
  for (const l of labels) {
    if (l === null || l === undefined) continue;
    if (typeof l === 'string') {
      const t = l.trim();
      if (t) out.push(t);
    } else if (typeof l === 'object') {
      const t = String(l.title ?? l.name ?? '').trim();
      if (t) out.push(t);
    }
  }
  return out;
}

const eventHeader = String(getHeader('x-gitlab-event') || body.event_type || body.object_kind || '').trim();
const event = eventHeader.toLowerCase();
if (!event.includes('issue')) {
  return [{ json: { ok: true, status_code: 200, skipped: true, reason: 'not_issue_event', event: eventHeader } }];
}

const token = String(getHeader('x-gitlab-token') || '').trim();
const scalarSecret = String(env.GITLAB_WEBHOOK_SECRET || '').trim();
const secretMap = resolveGitlabWebhookSecretsMap();

const projectPath = pickFirst(['project.path_with_namespace', 'project.path', 'project_path'], '') || '';
const realmFromProject = deriveRealmFromProjectPath(projectPath);

let expectedSecret = '';
if (secretMap && Object.keys(secretMap).length) {
  const candidates = [realmFromProject, (realmFromProject || '').toLowerCase(), 'default', '*'].filter(Boolean);
  for (const k of candidates) {
    const v = secretMap[k];
    if (v !== undefined && v !== null && String(v).trim()) {
      expectedSecret = String(v).trim();
      break;
    }
  }
}
if (!expectedSecret) expectedSecret = scalarSecret;

const hasAnySecret = Boolean(scalarSecret) || Boolean(expectedSecret) || (secretMap && Object.keys(secretMap).length);
if (hasAnySecret) {
  if (!token || !expectedSecret || token !== expectedSecret) {
    return [{
      json: {
        ok: false,
        status_code: 403,
        error: 'invalid_webhook_token',
        skipped: true,
        reason: 'invalid_webhook_token',
        realm: realmFromProject || null,
      }
    }];
  }
}

const dryRun = isTruthy(pickFirst(['dry_run'], false)) || isTruthy(env.ITSM_CIR_AUTO_LABEL_DRY_RUN);

const cirMarker = String(env.ITSM_CIR_TEMPLATE_MARKER || '<!-- itsm:cir:template=continual_improvement_register -->');
const cirLabel = String(env.ITSM_CIR_LABEL || 'ITSM/継続的改善');
const statusPrefix = String(env.ITSM_CIR_STATUS_PREFIX || '状態/');
const newStatusLabel = String(env.ITSM_CIR_NEW_LABEL || '状態/New');
const projectSuffix = String(env.ITSM_CIR_AUTO_LABEL_PROJECT_SUFFIX || '/general-management');

const issueIid = String(pickFirst(['object_attributes.iid', 'object_attributes.iid', 'issue.iid', 'iid'], '') || '').trim();
const issueId = pickFirst(['object_attributes.id', 'issue.id', 'id'], null);
const issueTitle = String(pickFirst(['object_attributes.title', 'issue.title', 'title'], '') || '').trim();
const issueDescription = String(pickFirst(['object_attributes.description', 'issue.description', 'description'], '') || '');

const labelsRaw = pickFirst(['labels', 'object_attributes.labels', 'issue.labels'], []);
const labels = normalizeLabels(labelsRaw);

if (!projectPath || !projectPath.endsWith(projectSuffix)) {
  return [{ json: { ok: true, status_code: 200, skipped: true, reason: 'not_general_management_project', project_path: projectPath || null } }];
}

const isCirTemplate = issueDescription.includes(cirMarker);
if (!isCirTemplate) {
  return [{ json: { ok: true, status_code: 200, skipped: true, reason: 'not_cir_template', project_path: projectPath || null, issue_iid: issueIid || null } }];
}

const statusLabels = labels.filter((l) => l.startsWith(statusPrefix));

const addLabels = [];
if (!labels.includes(cirLabel)) addLabels.push(cirLabel);
if (statusLabels.length === 0) addLabels.push(newStatusLabel);

if (addLabels.length === 0) {
  return [{
    json: {
      ok: true,
      status_code: 200,
      skipped: true,
      reason: 'labels_already_present',
      dry_run: dryRun,
      project_path: projectPath,
      issue_iid: issueIid || null,
      issue_id: issueId || null,
      issue_title: issueTitle || null,
      labels,
    }
  }];
}

const projectId = pickFirst(['project.id', 'project_id'], null);
const gitlabApiBaseUrl = String(env.N8N_GITLAB_API_BASE_URL || env.GITLAB_API_BASE_URL || '').replace(/\/+$/, '');
const gitlabToken = String(env.N8N_GITLAB_TOKEN || env.GITLAB_TOKEN || env.GITLAB_ADMIN_TOKEN || '').trim();

const missing = [];
if (!projectId) missing.push('project.id');
if (!issueIid) missing.push('object_attributes.iid');
if (!gitlabApiBaseUrl) missing.push('GITLAB_API_BASE_URL');
if (!gitlabToken) missing.push('GITLAB_TOKEN');

if (!dryRun && missing.length) {
  return [{ json: { ok: false, status_code: 424, error: 'missing_gitlab_config', missing } }];
}

return [{
  json: {
    ok: true,
    status_code: 200,
    dry_run: dryRun,
    project_id: projectId,
    project_path: projectPath,
    issue_iid: issueIid,
    issue_id: issueId || null,
    issue_title: issueTitle || null,
    current_labels: labels,
    add_labels: addLabels,
    gitlab_api_base_url: gitlabApiBaseUrl,
    missing,
  }
}];

const req = $json ?? {};
const env = $env || {};

function safeString(v) {
  const s = (v === undefined || v === null) ? '' : String(v);
  return s;
}

function uniq(list) {
  const out = [];
  const seen = new Set();
  for (const v of list || []) {
    const s = String(v ?? '').trim();
    if (!s) continue;
    if (seen.has(s)) continue;
    seen.add(s);
    out.push(s);
  }
  return out;
}

const dryRun = Boolean(req.dry_run);
const projectId = safeString(req.project_id);
const issueIid = safeString(req.issue_iid);
const addLabels = Array.isArray(req.add_labels) ? uniq(req.add_labels) : [];

if (dryRun) {
  return [{ json: { ...req, updated: false, planned: { add_labels: addLabels } } }];
}

const baseUrl = safeString(env.N8N_GITLAB_API_BASE_URL || env.GITLAB_API_BASE_URL).replace(/\/+$/, '');
const token = safeString(env.N8N_GITLAB_TOKEN || env.GITLAB_TOKEN || env.GITLAB_ADMIN_TOKEN).trim();

if (!baseUrl || !token) {
  return [{ json: { ...req, ok: false, status_code: 424, error: 'missing_gitlab_config_runtime' } }];
}

if (!projectId || !issueIid) {
  return [{ json: { ...req, ok: false, status_code: 400, error: 'missing_issue_identity' } }];
}

if (!addLabels.length) {
  return [{ json: { ...req, ok: true, status_code: 200, skipped: true, reason: 'no_labels_to_add' } }];
}

const issueUrl = `${baseUrl}/projects/${encodeURIComponent(projectId)}/issues/${encodeURIComponent(issueIid)}`;
const payload = { add_labels: addLabels.join(',') };

try {
  const updated = await this.helpers.httpRequest({
    method: 'PUT',
    url: issueUrl,
    json: true,
    timeout: 8000,
    headers: { 'PRIVATE-TOKEN': token },
    body: payload,
  });
  return [{
    json: {
      ...req,
      ok: true,
      status_code: 200,
      updated: true,
      added_labels: addLabels,
      after_labels: updated?.labels || null,
    }
  }];
} catch (err) {
  const status = err?.response?.statusCode || err?.statusCode || err?.httpCode || null;
  const responseBody = err?.response?.body || err?.response?.data || null;
  return [{
    json: {
      ...req,
      ok: false,
      status_code: status || 502,
      error: 'gitlab_update_issue_failed',
      detail: String(err?.message || err),
      response_body: responseBody,
    }
  }];
}
